        if s == s[::-1]:
            return int(s)
        # generate the next palindrome candidate by mirroring the left half to right
        length = len(s)
        half = length // 2
        if length % 2 == 0:
            left = s[:half]
            pal_candidate = left + left[::-1]
        else:
            left = s[:half+1]
            pal_candidate = left + left[:-1][::-1]

        if int(pal_candidate) >= int(s):
            s = pal_candidate
        else:
            # increment the middle part and rebuild palindrome
            if length % 2 == 0:
                # even length
                left_num = int(left) + 1
                left = str(left_num)
                pal_candidate = left + left[::-1]
